for T in AAPL MSFT NVDA JPM KO GME SPY; do
  curl -s --max-time 30 "$URL/api/snapshot?ticker=$T" | bun -e '
    const d = await Bun.stdin.json();
    if (d.error) console.log(("'"$T"'").padEnd(6), "-> ERROR:", d.error);
    else console.log(("'"$T"'").padEnd(6), "->", d.companyName.slice(0,32).padEnd(33), d.overall.light.toUpperCase(), d.cards.length?`(${d.cards.length} cards)`:"(quote-only)", d.dataNotes[0]??"");
  '
  sleep 1
done
